import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./AdminDashboard.css";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();
    socket.on("queueUpdated", fetchQueues);
    return () => socket.off("queueUpdated");
  }, []);

  const confirmOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/confirm/${id}`, {
      method: "PUT"
    });
  };

  const completeOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/complete/${id}`, {
      method: "DELETE"
    });
  };

  return (

    <div className="admin-page">

      <h1>HealSync Admin Panel</h1>

      <div className="queue-grid">

        {queues.map(q => (

          <div key={q._id} className="card">

            <h3>{q.patientName}</h3>
            <p>{q.department}</p>
            <p>Status: {q.status}</p>

            {q.status === "Waiting" && (
              <button onClick={() => confirmOP(q._id)}>
                Confirm OP
              </button>
            )}

            <button onClick={() => completeOP(q._id)}>
              Complete OP
            </button>

          </div>

        ))}

      </div>

    </div>

  );

}

export default AdminDashboard;
